INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13301, 'ស្វ៊ីតចំនួនពិតមួយជាស្វ៊ីតធរណីមាត្រ នៅពេលដែលមានចំនួនពិត \(q\) មិនសូន្យ ដែលគ្រប់ពាក្យបន្ទាប់គឺស្មើនឹងពាក្យមុនគុណនឹង ៖', NULL, '["\\(d\\)", "\\(n\\)", "\\(q\\)", "\\(q+d\\)"]', 2, NULL, 1, 'mcq', 'តាមនិយមន័យ ស្វ៊ីតធរណីមាត្រមានសមាមាត្ររួម \(q\) ដែល \(a_{n+1}=a_n q\)។', 'ស្វ៊ីតធរណីមាត្រ', 'easy', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13302, 'ប្រសិនបើ \((a_n)\) ជាស្វ៊ីតធរណីមាត្រ នោះសមាមាត្ររួមគឺ ៖', NULL, '["\\(q=\\dfrac{a_{n+1}}{a_n}\\)", "\\(q=a_n a_{n+1}\\)", "\\(q=\\dfrac{a_n}{a_{n+1}}\\)", "\\(q=a_{n+1}-a_n\\)"]', 0, NULL, 1, 'mcq', 'សមាមាត្ររួមជាផលធ្លាក់នៃពាក្យបន្ទាប់ចែកពាក្យមុន។', 'ស្វ៊ីតធរណីមាត្រ', 'easy', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13303, 'ពាក្យទូទៅនៃស្វ៊ីតធរណីមាត្រដែលមានពាក្យទី១ \(a_1\) និងសមាមាត្ររួម \(q\) គឺ ៖', NULL, '["\\(a_n=a_1 q^n\\)", "\\(a_n=a_1 q^{n-1}\\)", "\\(a_n=a_1+(n)q\\)", "\\(a_n=a_1+(n-1)q\\)"]', 1, NULL, 1, 'mcq', 'ពាក្យទី \(n\) បានមកពីគុណ \(a_1\) នឹង \(q\) ចំនួន \(n-1\) ដង។', 'ស្វ៊ីតធរណីមាត្រ', 'easy', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13304, 'មធ្យមធរណីមាត្រនៃចំនួនវិជ្ជមាន \(4\) និង \(9\) គឺ ៖', NULL, '["\\(6\\)", "\\(6.5\\)", "\\(36\\)", "\\(13\\)"]', 0, NULL, 1, 'mcq', '\(\sqrt{4\cdot 9}=\sqrt{36}=6\)។', 'ស្វ៊ីតធរណីមាត្រ', 'easy', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13305, 'ផលបូក \(1+2+4+8+16+32+64\) ស្មើនឹង ៖', NULL, '["\\(64\\)", "\\(63\\)", "\\(127\\)", "\\(128\\)"]', 2, NULL, 1, 'mcq', '\(S_n=a_1(q^n-1)/(q-1)=1(2^7-1)/(2-1)=127\)។', 'ស្វ៊ីតធរណីមាត្រ', 'easy', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13306, 'ស្វ៊ីតធរណីមាត្រមានផលបូកអនន្ត នៅពេល ៖', NULL, '["\\(q=1\\)", "\\(q=-1\\)", "\\(|q|>1\\)", "\\(|q|<1\\)"]', 3, NULL, 1, 'mcq', 'លក្ខខណ្ឌរួមគ្នានៃផលបូកអនន្តគឺ \(|q|<1\)។', 'ស្វ៊ីតធរណីមាត្រ', 'easy', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
