INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13307, 'សមាមាត្ររួមនៃស្វ៊ីត \(2,6,18,54,162,\ldots\) គឺ ៖', 'g11sc-75a0c2fcda.svg', '["\\(3\\)", "\\(6\\)", "\\(2\\)", "\\(4\\)"]', 0, NULL, 1, 'mcq', '\(q=a_{n+1}/a_n=6/2=3\)។ ពាក្យបន្ទាប់គុណនឹង ៣ ដដែល។', 'ស្វ៊ីតធរណីមាត្រ', 'easy', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13308, 'ស្វ៊ីត \(6,12,24,48,\ldots\) មានសមាមាត្ររួម ៖', NULL, '["\\(12\\)", "\\(6\\)", "\\(2\\)", "\\(1/2\\)"]', 2, NULL, 1, 'mcq', '\(12/6=24/12=2\)។', 'ស្វ៊ីតធរណីមាត្រ', 'easy', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13309, 'រូបមន្តផលបូក \(n\) ពាក្យដំបូងនៃស្វ៊ីតធរណីមាត្រ (\(q\neq 1\)) គឺ ៖', NULL, '["\\(S_n=a_1 q^n\\)", "\\(S_n=n a_1 q\\)", "\\(S_n=\\dfrac{a_1(q^n-1)}{q-1}\\)", "\\(S_n=\\dfrac{n}{2}(2a_1+(n-1)q)\\)"]', 2, NULL, 1, 'mcq', 'នេះជារូបមន្តស្តង់ដារនៃផលបូកស្វ៊ីតធរណីមាត្រ។', 'ស្វ៊ីតធរណីមាត្រ', 'easy', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13310, 'បើ \(|q|<1\) ផលបូកអនន្តនៃស្វ៊ីតធរណីមាត្រគឺ ៖', NULL, '["\\(S_\\infty=\\dfrac{a_1}{1-q}\\)", "\\(S_\\infty=\\dfrac{a_1}{q-1}\\)", "\\(S_\\infty=a_1(1-q)\\)", "\\(S_\\infty=a_1 q\\)"]', 0, NULL, 1, 'mcq', 'រូបមន្តស្តង់ដារ \(S_\infty=a_1/(1-q)\) នៅពេល \(|q|<1\)។', 'ស្វ៊ីតធរណីមាត្រ', 'easy', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13311, 'ក្នុងស្វ៊ីត \(6,12,24,48,\ldots\) ពាក្យទី ១៤ គឺ ៖', NULL, '["\\(24\\,576\\)", "\\(98\\,304\\)", "\\(49\\,152\\)", "\\(12\\,288\\)"]', 2, NULL, 2, 'mcq', '\(a_{14}=6\cdot 2^{13}=6\cdot 8\,192=49\,152\)។', 'ស្វ៊ីតធរណីមាត្រ', 'medium', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13312, 'ត្រូវបន្ថែមចំនួន \(x\) លើពាក្យនីមួយនៃ \(3,24,94\) ដើម្បីបានស្វ៊ីតធរណីមាត្រ។ តម្លៃ \(x\) គឺ ៖', NULL, '["\\(8\\)", "\\(6\\)", "\\(4\\)", "\\(3\\)"]', 1, NULL, 2, 'mcq', '\((24+x)^2=(3+x)(94+x)\Rightarrow 294=49x\Rightarrow x=6\)។', 'ស្វ៊ីតធរណីមាត្រ', 'medium', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13313, 'ផលបូក \(7\) ពាក្យដំបូងនៃ \(5+10+20+\cdots\) គឺ ៖', NULL, '["\\(315\\)", "\\(640\\)", "\\(635\\)", "\\(320\\)"]', 2, NULL, 2, 'mcq', '\(S_7=5(2^7-1)/(2-1)=5\cdot 127=635\)។', 'ស្វ៊ីតធរណីមាត្រ', 'medium', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13314, 'ផលបូកអនន្ត \(6+2+\dfrac{2}{3}+\dfrac{2}{9}+\cdots\) ស្មើនឹង ៖', NULL, '["\\(6\\)", "\\(9\\)", "\\(8\\)", "\\(12\\)"]', 1, NULL, 2, 'mcq', '\(a_1=6\), \(q=1/3\)។ \(S_\infty=6/(1-1/3)=9\)។', 'ស្វ៊ីតធរណីមាត្រ', 'medium', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
