INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13315, 'ក្នុងស្វ៊ីតធរណីមាត្រមាន \(n\) ពាក្យ ផលគុណនៃពាក្យស្មើចម្ងាយពីចុងស្វ៊ីតស្មើនឹង ៖', 'g11sc-0f2a0a36b6.svg', '["\\(n a_1\\)", "\\(a_n/a_1\\)", "\\(a_1 a_n\\)", "\\(a_1+a_n\\)"]', 2, NULL, 2, 'mcq', '\(a_p a_{n-p+1}=a_1 a_n\)។', 'ស្វ៊ីតធរណីមាត្រ', 'medium', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13316, 'ក្នុងស្វ៊ីត \(6,12,24,48,\ldots\) ពាក្យ \(384\) ជាពាក្យទី ៖', NULL, '["\\(6\\)", "\\(9\\)", "\\(8\\)", "\\(7\\)"]', 3, NULL, 2, 'mcq', '\(6\cdot 2^{n-1}=384\Rightarrow 2^{n-1}=64=2^6\Rightarrow n=7\)។', 'ស្វ៊ីតធរណីមាត្រ', 'medium', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13317, 'ផលបូក \(2+6+18+\cdots+1\,458\) គឺ ៖', NULL, '["\\(2\\,187\\)", "\\(2\\,186\\)", "\\(1\\,458\\)", "\\(1\\,093\\)"]', 1, NULL, 2, 'mcq', '\(a_n=2\cdot 3^{n-1}=1\,458\Rightarrow 3^{n-1}=729=3^6\Rightarrow n=7\)។ \(S_7=2(3^7-1)/(3-1)=2\,187-1=2\,186\)។', 'ស្វ៊ីតធរណីមាត្រ', 'medium', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13318, 'ផលបូកអនន្ត \(16+12+9+\cdots\) គឺ ៖', NULL, '["\\(48\\)", "\\(32\\)", "\\(64\\)", "\\(36\\)"]', 2, NULL, 2, 'mcq', '\(q=12/16=3/4\) ហើយ \(S_\infty=16/(1-3/4)=64\)។', 'ស្វ៊ីតធរណីមាត្រ', 'medium', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13319, 'ក្នុងស្វ៊ីត \(3,12,48,192,\ldots\) ពាក្យទី ៩ គឺ ៖', NULL, '["\\(786\\,432\\)", "\\(196\\,608\\)", "\\(49\\,152\\)", "\\(65\\,536\\)"]', 1, NULL, 2, 'mcq', '\(a_9=3\cdot 4^{8}=3\cdot 65\,536=196\,608\)។', 'ស្វ៊ីតធរណីមាត្រ', 'medium', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13320, 'ផលបូក \(7\) ពាក្យដំបូងនៃ \(6+3+1.5+\cdots\) គឺ ៖', NULL, '["\\(\\dfrac{381}{16}\\)", "\\(12\\)", "\\(\\dfrac{63}{8}\\)", "\\(\\dfrac{381}{32}\\)"]', 3, NULL, 2, 'mcq', '\(S_7=6\bigl((1/2)^7-1\bigr)/(1/2-1)=381/32\)។', 'ស្វ៊ីតធរណីមាត្រ', 'medium', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13321, 'ប្រភាគទសភាគ \(0.\overline{235}\) ស្មើនឹង ៖', NULL, '["\\(\\dfrac{235}{1\\,000}\\)", "\\(\\dfrac{23}{99}\\)", "\\(\\dfrac{235}{999}\\)", "\\(\\dfrac{235}{99}\\)"]', 2, NULL, 2, 'mcq', '\(0.\overline{235}=235/10^3+235/10^6+\cdots=(235/1\,000)/(1-1/1\,000)=235/999\)។', 'ស្វ៊ីតធរណីមាត្រ', 'medium', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13322, 'ក្នុងស្វ៊ីត \(3,12,48,192,\ldots\) ពាក្យ \(12\,288\) ជាពាក្យទី ៖', NULL, '["\\(6\\)", "\\(8\\)", "\\(5\\)", "\\(7\\)"]', 3, NULL, 2, 'mcq', '\(3\cdot 4^{n-1}=12\,288\Rightarrow 4^{n-1}=4\,096=4^6\Rightarrow n=7\)។', 'ស្វ៊ីតធរណីមាត្រ', 'medium', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13323, 'បើ \(q=1\) នោះផលបូក \(n\) ពាក្យដំបូងនៃស្វ៊ីតធរណីមាត្រគឺ ៖', NULL, '["\\(S_n=0\\)", "\\(S_n=a_1\\)", "\\(S_n=a_1(q^n-1)\\)", "\\(S_n=n a_1\\)"]', 3, NULL, 2, 'mcq', 'ពេល \(q=1\) ពាក្យទាំងអស់ស្មើ \(a_1\) ដូច្នេះ \(S_n=n a_1\)។', 'ស្វ៊ីតធរណីមាត្រ', 'medium', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13324, 'ប្រភាគទសភាគ \(4.\overline{57}\) ស្មើនឹង ៖', NULL, '["\\(\\dfrac{4}{57}\\)", "\\(\\dfrac{457}{99}\\)", "\\(\\dfrac{57}{99}\\)", "\\(\\dfrac{453}{99}\\)"]', 3, NULL, 2, 'mcq', '\(4.\overline{57}=4+57/99=396/99+57/99=453/99\)។', 'ស្វ៊ីតធរណីមាត្រ', 'medium', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13325, 'ក្នុងស្វ៊ីត \(1,2,4,8,\ldots\) ពាក្យ \(8\,192\) ជាពាក្យទី ៖', NULL, '["\\(14\\)", "\\(12\\)", "\\(15\\)", "\\(13\\)"]', 0, NULL, 3, 'mcq', '\(2^{n-1}=8\,192=2^{13}\Rightarrow n=14\)។', 'ស្វ៊ីតធរណីមាត្រ', 'hard', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13326, 'ស្វ៊ីតធរណីមាត្រមាន \(a_1=3\) និង \(S_3=21\) (\(q>0\))។ ផលបូក \(S_7\) គឺ ៖', NULL, '["\\(765\\)", "\\(192\\)", "\\(381\\)", "\\(255\\)"]', 2, NULL, 3, 'mcq', '\((q^2+q+1)=7\Rightarrow q=2\)។ \(S_7=3(2^7-1)=381\)។', 'ស្វ៊ីតធរណីមាត្រ', 'hard', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13327, 'ស្វ៊ីតធរណីមាត្រមាន \(a_2=-9\) និង \(a_5=1/3\)។ ផលបូកអនន្តគឺ ៖', NULL, '["\\(\\dfrac{27}{4}\\)", "\\(-9\\)", "\\(27\\)", "\\(\\dfrac{81}{4}\\)"]', 3, NULL, 3, 'mcq', '\(q^3=-1/27\Rightarrow q=-1/3\)។ \(a_1=27\)។ \(S_\infty=27/(1+1/3)=81/4\)។', 'ស្វ៊ីតធរណីមាត្រ', 'hard', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13328, 'ក្នុងស្វ៊ីត \(20,10,5,\ldots\) ពាក្យ \(5/256\) ជាពាក្យទី ៖', NULL, '["\\(16\\)", "\\(8\\)", "\\(12\\)", "\\(10\\)"]', 2, NULL, 3, 'mcq', '\(20\cdot(1/2)^{n-1}=5/256\Rightarrow 2^{4-n}=2^{-8}\Rightarrow n=12\)។', 'ស្វ៊ីតធរណីមាត្រ', 'hard', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13329, 'ផលបូក \(48+24+12+\cdots+3/8\) គឺ ៖', NULL, '["\\(\\dfrac{381}{4}\\)", "\\(48\\)", "\\(\\dfrac{765}{8}\\)", "\\(96\\)"]', 2, NULL, 3, 'mcq', '\(n=8\) និង \(S_8=48\bigl(1-(1/2)^8\bigr)/(1/2)=765/8\)។', 'ស្វ៊ីតធរណីមាត្រ', 'hard', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13330, 'បើ \(a_1=5\) និង \(S_\infty=15\) នោះសមាមាត្ររួមគឺ ៖', NULL, '["\\(\\dfrac{2}{3}\\)", "\\(\\dfrac{1}{3}\\)", "\\(\\dfrac{1}{5}\\)", "\\(\\dfrac{3}{5}\\)"]', 0, NULL, 3, 'mcq', '\(5/(1-q)=15\Rightarrow 1-q=1/3\Rightarrow q=2/3\)។', 'ស្វ៊ីតធរណីមាត្រ', 'hard', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13331, 'ស្វ៊ីតធរណីមាត្រមាន \(a_3=18\) និង \(a_7=1\,458\) (\(q>0\))។ ពាក្យទី ១០ គឺ ៖', NULL, '["\\(13\\,122\\)", "\\(4\\,374\\)", "\\(39\\,366\\)", "\\(19\\,683\\)"]', 2, NULL, 3, 'mcq', '\(q^4=1\,458/18=81\Rightarrow q=3\)។ \(a_1=18/9=2\)។ \(a_{10}=2\cdot 3^9=39\,366\)។', 'ស្វ៊ីតធរណីមាត្រ', 'hard', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13332, 'ប្រជាជនប្រទេសមួយឆ្នាំ ២០០០ មាន ២ លាននាក់ ហើយកើន ៤% រាល់ឆ្នាំ។ ចំនួនប្រជាជនឆ្នាំ ២០០៩ ជិតបំផុតនឹង ៖', NULL, '["២.៧២ លាននាក់", "២.៤០ លាននាក់", "៣.១២ លាននាក់", "២.៨៥ លាននាក់"]', 3, NULL, 3, 'mcq', '\(a_{10}=2\cdot(1.04)^9\approx 2.8466\) លាននាក់។', 'ស្វ៊ីតធរណីមាត្រ', 'pisa', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
