INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13335, 'ប៉ោលយោលដំបូងបានធ្នូ ២៤ dm រួចប្រវែងធ្នូថយ ២០% រាល់លើក។ ប្រវែងគន្លងសរុបរហូតឈប់គឺ ៖', 'g11sc-021b0446fa.svg', '["\\(96\\) dm", "\\(120\\) dm", "\\(240\\) dm", "\\(48\\) dm"]', 1, NULL, 3, 'mcq', '\(a_1=24\), \(q=0.8\)។ \(S_\infty=24/(1-0.8)=120\) dm។', 'ស្វ៊ីតធរណីមាត្រ', 'pisa', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13336, 'ដាក់ប្រាក់ ១០០ ០០០ រៀល ផ្តល់ការប្រាក់ ៦% ក្នុងមួយឆ្នាំ (រួមប្រាក់)។ ប្រាក់សរុបក្រោយ \(n\) ឆ្នាំគឺ ៖', NULL, '["\\(100\\,000\\cdot 1.06 n\\)", "\\(100\\,000+6\\,000n\\)", "\\(100\\,000\\cdot(0.06)^n\\)", "\\(100\\,000\\cdot(1.06)^n\\)"]', 3, NULL, 3, 'mcq', 'ការប្រាក់រួមគឺស្វ៊ីតធរណីមាត្រ \(a_n=a_0(1+r)^n\)។', 'ស្វ៊ីតធរណីមាត្រ', 'pisa', 1, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13337, 'និយមន័យស្វ៊ីតធរណីមាត្រ រួមនឹងរូបមន្តពាក្យទូទៅ និងផលបូក \(n\) ពាក្យ។', NULL, '[]', 0, NULL, 5, 'writing', 'ស្វ៊ីតធរណីមាត្រមានសមាមាត្ររួមថេរ \(q=a_{n+1}/a_n\neq 0\)។ (1 ពិន្ទុ)
ពាក្យទូទៅ ៖ \(a_n=a_1 q^{n-1}\)។ (1 ពិន្ទុ)
ផលបូក ៖ \(S_n=a_1(q^n-1)/(q-1)\) បើ \(q\neq 1\)។ (1 ពិន្ទុ)
បើ \(q=1\) នោះ \(S_n=n a_1\)។ (1 ពិន្ទុ)
បើ \(|q|<1\) មានផលបូកអនន្ត \(S_\infty=a_1/(1-q)\)។ (1 ពិន្ទុ)', 'ស្វ៊ីតធរណីមាត្រ', 'easy', 0, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13338, 'រកពាក្យទី ១៤ និងលំដាប់នៃពាក្យ ៣៨៤ ក្នុងស្វ៊ីត \(6,12,24,48,\ldots\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ \(q=12/6=2\)។ (1 ពិន្ទុ)
សរសេរ \(a_n=6\cdot 2^{n-1}\)។ (1 ពិន្ទុ)
\(a_{14}=6\cdot 2^{13}=6\cdot 8\,192=49\,152\)។ (1 ពិន្ទុ)
\(6\cdot 2^{n-1}=384\Rightarrow 2^{n-1}=64=2^6\)។ (1 ពិន្ទុ)
ដូច្នេះ \(n=7\)។ (1 ពិន្ទុ)', 'ស្វ៊ីតធរណីមាត្រ', 'medium', 0, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13339, 'រក \(x\) ដែលបន្ថែមលើ \(3,24,94\) ឲ្យបានស្វ៊ីតធរណីមាត្រ។', NULL, '[]', 0, NULL, 5, 'writing', 'លក្ខខណ្ឌ ៖ \((24+x)^2=(3+x)(94+x)\)។ (1 ពិន្ទុ)
ពន្លាត ៖ \(576+48x+x^2=282+97x+x^2\)។ (1 ពិន្ទុ)
\(294=49x\)។ (1 ពិន្ទុ)
\(x=6\)។ (1 ពិន្ទុ)
ស្វ៊ីតថ្មី ៖ \(9,30,100\)។ (1 ពិន្ទុ)', 'ស្វ៊ីតធរណីមាត្រ', 'medium', 0, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13340, 'គណនា \(S_7\) នៃ \(5+10+20+\cdots\) និងផលបូក \(2+6+18+\cdots+1\,458\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ស្វ៊ីតទី១ ៖ \(a_1=5\), \(q=2\)។ (1 ពិន្ទុ)
\(S_7=5(2^7-1)=635\)។ (1 ពិន្ទុ)
\(2\cdot 3^{n-1}=1\,458\Rightarrow 3^{n-1}=729=3^6\Rightarrow n=7\)។ (1 ពិន្ទុ)
\(S_7=2(3^7-1)/2=2\,186\)។ (1 ពិន្ទុ)
សន្និដ្ឋានផលបូកទាំងពីរ ៖ ៦៣៥ និង ២១៨៦។ (1 ពិន្ទុ)', 'ស្វ៊ីតធរណីមាត្រ', 'medium', 0, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13341, 'បង្ហាញថា \(0.\overline{235}=235/999\) ដោយប្រើផលបូកអនន្ត។', NULL, '[]', 0, NULL, 5, 'writing', '\(0.\overline{235}=235/10^3+235/10^6+\cdots\)។ (1 ពិន្ទុ)
\(a_1=235/1\,000\), \(q=1/1\,000\)។ (1 ពិន្ទុ)
ពិនិត្យ \(|q|<1\)។ (1 ពិន្ទុ)
\(S=a_1/(1-q)=(235/1\,000)/(999/1\,000)\)។ (1 ពិន្ទុ)
\(S=235/999\)។ (1 ពិន្ទុ)', 'ស្វ៊ីតធរណីមាត្រ', 'medium', 0, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13342, 'ស្វ៊ីតមាន \(a_1=3\) និង \(S_3=21\) (\(q>0\))។ រក \(q\) និង \(S_7\)។', NULL, '[]', 0, NULL, 5, 'writing', '\(S_3=3(q^2+q+1)=21\)។ (1 ពិន្ទុ)
\(q^2+q-6=0\)។ (1 ពិន្ទុ)
\((q+3)(q-2)=0\) និង \(q>0\Rightarrow q=2\)។ (1 ពិន្ទុ)
\(S_7=3(2^7-1)/(2-1)\)។ (1 ពិន្ទុ)
\(S_7=381\)។ (1 ពិន្ទុ)', 'ស្វ៊ីតធរណីមាត្រ', 'hard', 0, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13343, 'ស្វ៊ីតមាន \(a_2=-9\) និង \(a_5=1/3\)។ រក \(q\), \(a_1\) និង \(S_\infty\)។', NULL, '[]', 0, NULL, 5, 'writing', '\(q^3=a_5/a_2=(1/3)/(-9)=-1/27\)។ (1 ពិន្ទុ)
\(q=-1/3\)។ (1 ពិន្ទុ)
\(a_1=a_2/q=27\)។ (1 ពិន្ទុ)
ពិនិត្យ \(|q|<1\)។ (1 ពិន្ទុ)
\(S_\infty=27/(1+1/3)=81/4\)។ (1 ពិន្ទុ)', 'ស្វ៊ីតធរណីមាត្រ', 'hard', 0, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13344, 'ស្វ៊ីតមាន \(a_3=18\) និង \(a_7=1\,458\) (\(q>0\))។ រក \(a_{10}\)។', NULL, '[]', 0, NULL, 5, 'writing', '\(q^4=1\,458/18=81\)។ (1 ពិន្ទុ)
\(q=3\)។ (1 ពិន្ទុ)
\(a_1=18/9=2\)។ (1 ពិន្ទុ)
\(a_{10}=2\cdot 3^9\)។ (1 ពិន្ទុ)
\(a_{10}=39\,366\)។ (1 ពិន្ទុ)', 'ស្វ៊ីតធរណីមាត្រ', 'hard', 0, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13345, 'គណនាផលបូក \(48+24+12+\cdots+3/8\)។', NULL, '[]', 0, NULL, 5, 'writing', '\(q=24/48=1/2\)។ (1 ពិន្ទុ)
\(48\cdot(1/2)^{n-1}=3/8\)។ (1 ពិន្ទុ)
\(n=8\)។ (1 ពិន្ទុ)
\(S_8=48(1-2^{-8})/(1/2)\)។ (1 ពិន្ទុ)
\(S_8=765/8\)។ (1 ពិន្ទុ)', 'ស្វ៊ីតធរណីមាត្រ', 'hard', 0, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13346, 'ប្រជាជនឆ្នាំ ២០០០ មាន ២ លាននាក់ កើន ៤% រាល់ឆ្នាំ។ សរសេររូបមន្ត \(a_n\) ហើយគណនាឆ្នាំ ២០០៩។', NULL, '[]', 0, NULL, 5, 'writing', 'ឆ្នាំ ២០០០ ជាពាក្យទី១ ៖ \(a_1=2\) លាននាក់។ (1 ពិន្ទុ)
\(q=1.04\)។ (1 ពិន្ទុ)
\(a_n=2\cdot(1.04)^{n-1}\)។ (1 ពិន្ទុ)
ឆ្នាំ ២០០៩ ជាពាក្យទី១០។ (1 ពិន្ទុ)
\(a_{10}=2\cdot(1.04)^9\approx 2.85\) លាននាក់។ (1 ពិន្ទុ)', 'ស្វ៊ីតធរណីមាត្រ', 'pisa', 0, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13347, 'ពន្យល់ចំនួនស្រូវសរុបលើក្តារអុក ៦៤ ប្រឡោះ (១, ២, ៤, …)។', NULL, '[]', 0, NULL, 5, 'writing', '\(a_1=1\), \(q=2\), \(n=64\)។ (1 ពិន្ទុ)
\(a_n=2^{n-1}\)។ (1 ពិន្ទុ)
\(S_{64}=(2^{64}-1)/(2-1)\)។ (1 ពិន្ទុ)
\(S_{64}=2^{64}-1=18\,446\,744\,073\,709\,551\,615\) គ្រាប់។ (1 ពិន្ទុ)
ប្រៀបធៀបនឹងទិន្នផលស្រូវកម្ពុជា \(5\times 10^6\) តោនក្នុងមួយឆ្នាំ។ (1 ពិន្ទុ)', 'ស្វ៊ីតធរណីមាត្រ', 'pisa', 0, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13348, 'ប៉ោលយោលដំបូងបានធ្នូ ២៤ dm រួចប្រវែងធ្នូថយ ២០% រាល់លើក។ រកប្រវែងគន្លងសរុបរហូតឈប់។', NULL, '[]', 0, NULL, 5, 'writing', '\(a_1=24\) dm។ (1 ពិន្ទុ)
\(q=80\%=0.8\)។ (1 ពិន្ទុ)
ពិនិត្យ \(|q|<1\)។ (1 ពិន្ទុ)
\(S_\infty=24/(1-0.8)\)។ (1 ពិន្ទុ)
\(S_\infty=120\) dm។ (1 ពិន្ទុ)', 'ស្វ៊ីតធរណីមាត្រ', 'pisa', 0, '11SC', 'ស្វ៊ីតធរណីមាត្រ', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13349, 'ដាក់ប្រាក់ ១០០ ០០០ រៀល ការប្រាក់រួម ៦% ក្នុងមួយឆ្នាំ។ សរសេរប្រាក់ក្រោយ \(n\) ឆ្នាំ និងក្រោយ ៥ ឆ្នាំ។', NULL, '[]', 0, NULL, 5, 'writing', 'ដើមទុន \(A_0=100\,000\) រៀល។ (1 ពិន្ទុ)
\(q=1.06\)។ (1 ពិន្ទុ)
\(A_n=100\,000\cdot(1.06)^n\)។ (1 ពិន្ទុ)
